#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
generate_slots.py  (chicken_1)
===============================
Generador automático de slots de animación para chicken_1.

USO:
    python generate_slots.py historia_chicken_1.json [--start-slot N] [--start-frame N] [--output-dir ./slots]
    (también funciona sin argumentos: busca el .json en la carpeta padre y pregunta)

ARGUMENTOS:
    historia_chicken_1.json   Archivo JSON con la trayectoria grabada (recorrido.key_points)
    --start-slot N            Número del primer slot a generar (default: 1)
    --start-frame N           Frame de Blender donde comienza la animación (default: 1)
    --output-dir DIR          Carpeta donde se guardan los .py generados (default: ./slots_generados)

LÓGICA DE DETECCIÓN (idéntica al generador de Alfred, sobre key_points.coordinates):
    - Z sube entre dos puntos consecutivos  → slot saltar_subir  (2 puntos, 40 frames, velocidad +50%)
    - Z baja entre dos puntos consecutivos  → slot saltar_bajar  (2 puntos, 33 frames, velocidad +50%)
    - Z constante en N puntos consecutivos  → slot caminar       (N puntos, ciclo de 41 frames por tramo, velocidad +50%)

ORIGEN DE LOS KEYFRAMES:
    Los diccionarios KEYFRAMES_SALTAR_SUBIR / KEYFRAMES_SALTAR_BAJAR / KEYFRAMES_CAMINAR_CYCLE
    de este archivo fueron extraídos directamente de las animaciones base de chicken_1
    generadas con General Animation Studio v2.1 (slot_001_saltar_subir.py, slot_001_saltar_bajar.py
    y slot_001_caminar.py), conservando los 24 huesos reales del armature 'Armature_chicken_1'
    (Root_M_chicken_1, Spine1_M_chicken_1, Chest_M_chicken_1, Neck_M_chicken_1, Head_M_chicken_1,
    Jaw_M_chicken_1, Scapula_R/L_chicken_1, Elbow_R/L_chicken_1, Hip_R/L_chicken_1,
    Knee_R/L_chicken_1, Ankle_R/L_chicken_1, no_bone_01..08).

    IMPORTANTE - supuesto de diseño para 'caminar':
    La animación base de caminar capturada en chicken_1 es UN solo ciclo de 62 frames
    para un único tramo recto. Como historia_chicken_1.json puede traer tramos de 'caminar'
    con más de 2 puntos consecutivos a la misma Z, este script REPITE el ciclo de 62 frames
    una vez por cada par de puntos consecutivos del tramo (no estira/comprime el ciclo por
    distancia, como sí hacía el generador biped de Alfred). Si tus puntos de caminar están
    muy separados entre sí, revisa visualmente el resultado en Blender; puede que necesites
    ajustar manualmente la velocidad de traslación del root.

    No hay ningún nombre de personaje hardcodeado fuera de estos datos extraídos: todo lo
    demás (rutas, nombres de archivo, slot, frame) se calcula a partir del JSON de entrada.
"""

