def _scale_wing_keyframes(kf_dict, factor, wing_bones=WING_BONES_CHICKEN_1):
    """
    NUEVO (Kebyn, 2026-09-02): devuelve una COPIA de kf_dict con las
    rotaciones de los huesos de ala multiplicadas por `factor` (acentua el
    aleteo), dejando el resto de los huesos y el dict original intactos --
    no se muta KEYFRAMES_SALTAR_BAJAR, que sigue usandose tal cual en
    generate_saltar_bajar().
    """
    out = {}
    for bone, kfs in kf_dict.items():
        if bone in wing_bones:
            out[bone] = {f: (rx * factor, ry * factor, rz * factor)
                         for f, (rx, ry, rz) in kfs.items()}
        else:
            out[bone] = kfs
    return out

