# ============================================================
# DETECCIÓN DE TIPO DE MOVIMIENTO Y AGRUPACIÓN DE SEGMENTOS
# ============================================================

def detect_movement_type(p_current, p_next):
    """Detecta el tipo de movimiento entre dos puntos consecutivos.

    PORT (2026-08-10, desde alfred_animation_studio): si el punto es
    identico al anterior (misma x/y/z), se clasifica como "parada" en
    vez de "caminar". Sin esto, el punto duplicado que inserta
    _expand_points_with_paradas() se fusionaba silenciosamente dentro
    del tramo de caminata anterior (dz==0 -> 'caminar'), y nunca se
    generaba un segmento de parada real -- el personaje seguia
    "caminando" con distancia cero en vez de quedarse quieto heredando
    la orientacion del tramo previo.
    """
    c0 = p_current['coordinates']
    c1 = p_next['coordinates']
    if c0['x'] == c1['x'] and c0['y'] == c1['y'] and c0['z'] == c1['z']:
        return 'parada'
    # BUGFIX (Kebyn, 2026-09-02): tolerancia para ruido de punto flotante
    # de calc_center_median() @ matrix_world -- ver EPSILON_Z en
    # path_recorder.py (_detect_move), ambas funciones deben coincidir.
    dz = c1['z'] - c0['z']
    EPSILON_Z = 1e-3
    if dz > EPSILON_Z:
        return 'saltar_subir'
    elif dz < -EPSILON_Z:
        return 'saltar_bajar'
    else:
        return 'caminar'


def group_segments(key_points):
    """
    Recorre los puntos y agrupa consecutivos del mismo tipo en segmentos.
    Retorna lista de dicts: {type, points}
    Reglas:
      - saltar_subir / saltar_bajar: siempre exactamente 2 puntos
      - parada: siempre exactamente 2 puntos (identicos) — PORT 2026-08-10
      - saltar: siempre exactamente 3 puntos (despegue/pico/aterrizaje),
        marcado a mano por el usuario -- NUEVO 2026-09-02, ver
        key_points[i]['tipo_marcado'] == 'SALTAR' (propagado desde
        pt.tipo_segmento en path_recorder.py)
      - caminar: todos los consecutivos con Z igual (y sin ser el mismo
        punto) se agrupan en un solo slot
    """
    segments = []
    i = 0
    n = len(key_points)

    while i < n - 1:
        # NUEVO (Kebyn, 2026-09-02): salto explicito de 3 puntos consecutivos.
        # Si no alcanzan los puntos restantes, se ignora el marcador y cae al
        # comportamiento normal (mismo criterio que _group_segments() en
        # path_recorder.py, ambos deben coincidir).
        if key_points[i].get('tipo_marcado') == 'SALTAR' and i < n - 2:
            segments.append({
                'type': 'saltar',
                'points': [key_points[i], key_points[i + 1], key_points[i + 2]]
            })
            i += 2
            continue

        # NUEVO (Kebyn, 2026-09-04): acciones de campo (picotear/acicalarse/
        # aletear/rascar), marcadas a mano en 1 sola coordenada -- mismo
        # mecanismo de duplicado de punto que PARADA (ver
        # _expand_points_with_paradas() en path_recorder.py), pero con un
        # tipo_marcado propio para que no se generen como 'parada' generico.
        if key_points[i].get('tipo_marcado') in ACCIONES_PUNTUALES_CAMPO:
            segments.append({
                'type': key_points[i]['tipo_marcado'].lower(),
                'points': [key_points[i], key_points[i + 1]]
            })
            i += 1
            continue

        move_type = detect_movement_type(key_points[i], key_points[i + 1])

        if move_type in ('saltar_subir', 'saltar_bajar', 'parada'):
            segments.append({
                'type': move_type,
                'points': [key_points[i], key_points[i + 1]]
            })
            i += 1
        else:  # caminar
            group = [key_points[i]]
            # BUGFIX (Kebyn, 2026-09-02): mismo corte que en _group_segments()
            # de path_recorder.py -- el while interno solo miraba Z, asi que
            # en terreno plano se tragaba el punto marcado 'SALTAR' dentro
            # del mismo tramo de caminata sin dejarle una vuelta al while
            # externo para armar el segmento de salto.
            while (i < n - 1
                   and detect_movement_type(key_points[i], key_points[i + 1]) == 'caminar'
                   and key_points[i].get('tipo_marcado') != 'SALTAR'):
                group.append(key_points[i + 1])
                i += 1
            segments.append({
                'type': 'caminar',
                'points': group
            })

    return segments


# ============================================================
# GENERADORES DE CÓDIGO PYTHON POR TIPO
# ============================================================

def _fmt_keyframes(kf_dict, start_frame):
    """Convierte keyframes relativos (0-based) a frames absolutos y los formatea como código Python."""
    lines = []
    lines.append("KEYFRAME_DATA = {")
    for bone, frames in kf_dict.items():
        lines.append(f"    '{bone}': {{")
        for rel_frame, rot in frames.items():
            abs_frame = start_frame + rel_frame
            lines.append(f"        {abs_frame}: ({rot[0]:.6f}, {rot[1]:.6f}, {rot[2]:.6f}),")
        lines.append("    },")
    lines.append("}")
    return "\n".join(lines)


def _fmt_keyframes_tiled(kf_dict, start_frame, n_repeats):
    """
    Igual que _fmt_keyframes pero repite el ciclo n_repeats veces consecutivas,
    encadenando los frames (usado para 'caminar' con más de 2 puntos).
    El último frame de una repetición y el primero de la siguiente coinciden
    en pose (el ciclo empieza y termina en pose 'parado'), así que se evita
    duplicar ese frame para no generar un keyframe doble en el mismo número.
    """
    cycle_len = max(kf_dict[next(iter(kf_dict))].keys()) + 1  # nº de frames del ciclo (p.ej. 62)
    lines = ["KEYFRAME_DATA = {"]
    for bone, frames in kf_dict.items():
        lines.append(f"    '{bone}': {{")
        for rep in range(n_repeats):
            base = start_frame + rep * (cycle_len - 1)
            for rel_frame, rot in frames.items():
                if rep > 0 and rel_frame == 0:
                    continue  # ya quedó puesto como último frame de la repetición anterior
                abs_frame = base + rel_frame
                lines.append(f"        {abs_frame}: ({rot[0]:.6f}, {rot[1]:.6f}, {rot[2]:.6f}),")
        lines.append("    },")
    lines.append("}")
    return "\n".join(lines)


def _fmt_trajectory(points):
    """Formatea los puntos de trayectoria como código Python."""
    lines = ["EMBEDDED_TRAJECTORY_POINTS = ["]
    for p in points:
        c = p['coordinates']
        lines.append("    {")
        lines.append(f"        \"index\": {p['index']},")
        lines.append(f"        \"coordinates\": {{\"x\": {c['x']}, \"y\": {c['y']}, \"z\": {c['z']}}},")
        lines.append(f"        \"texture\": \"{p.get('texture', '')}\",")
        lines.append(f"        \"face_index\": \"{p.get('face_index', '')}\"")
        lines.append("    },")
    lines.append("]")
    return "\n".join(lines)


# ============================================================
# HELPERS DE DIRECCIÓN - usados por los 3 generadores de slots
# ============================================================

def _compute_direction_angle(p0, p1):
    """
    Calcula el ángulo de orientación del personaje dado un vector de movimiento.
    Cardinal vs diagonal + corrección Blender.
    Retorna grados flotantes en [-180, 180]. None si no hay componente horizontal.
    """
    import math as _math
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = _math.degrees(_math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    if ang_diff < 45:
        ang = ang_rounded
    else:
        ang = -ang_raw
    while ang > 180:  ang -= 360
    while ang < -180: ang += 360
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang


def _smoothstep_val(x):
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)


def _angle_diff_shortest(target, current):
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d


def _fmt_root_arc(p0, p1, start_frame, total_frames, min_clearance=1.0):
    """
    CORREGIDO (fix atravesar bloque en saltar_subir/saltar_bajar):
    Antes ROOT_LOCATION_DATA solo tenia 2 keyframes (inicio y fin), lo que
    genera una linea recta entre "a" y "b" -- el personaje atraviesa el
    bloque que deberia saltar (ver Imagen 1 del reporte).

    Esta funcion genera una trayectoria en arco/parabola (varios keyframes
    intermedios) igual que en la Imagen 2: sube en curva por encima del
    punto mas alto de origen/destino y desciende hacia el destino, en vez
    de moverse en linea recta. La altura del arco (H) se calcula para que
    siempre libre un bloque de 1m (escala Minecraft 1 block = 1m) mas un
    margen, sin importar que tan lejos o que tan parecida sea la altura
    entre "a" y "b".

    Retorna (texto_python_del_dict, altura_del_arco_usada).
    """
    ox, oy, oz = p0['x'], p0['y'], p0['z']
    dx = p1['x'] - ox
    dy = p1['y'] - oy
    dz = p1['z'] - oz
    dist_xy = math.sqrt(dx * dx + dy * dy)

    # Altura del arco por encima del punto mas alto de los dos extremos:
    # al menos min_clearance (1 bloque) para no atravesar el bloque saltado,
    # y mas alto todavia si el salto es largo o el desnivel es grande.
    H = max(min_clearance, abs(dz) * 0.75 + min_clearance * 0.5, dist_xy * 0.5)

    end_frame = start_frame + total_frames - 1
    n_samples = min(total_frames, 11)
    stride = max(1, (total_frames - 1) // (n_samples - 1))
    rel_frames = list(range(0, total_frames - 1, stride))
    rel_frames.append(total_frames - 1)
    # quitar duplicados preservando orden (por si el stride no divide exacto)
    seen = set()
    rel_frames = [rf for rf in rel_frames if not (rf in seen or seen.add(rf))]

    lines = ["ROOT_LOCATION_DATA = {"]
    for rf in rel_frames:
        t = rf / max(total_frames - 1, 1)
        t_s = t * t * (3.0 - 2.0 * t)          # smoothstep: ease-in / ease-out
        arc = 4.0 * H * t_s * (1.0 - t_s)      # parabola: 0 en los extremos, H en el medio
        x = ox + t_s * dx
        y = oy + t_s * dy
        z = oz + t_s * dz + arc
        frame = start_frame + rf
        lines.append(f"    {frame}: ({x:.6f}, {y:.6f}, {z:.6f}),")
    lines.append("}")
    assert rel_frames[0] == 0 and rel_frames[-1] == total_frames - 1
    return "\n".join(lines), H


def _fmt_root_arc_3pt(a, b, c, start_frame, total_frames, height=1.0):
    """
    NUEVO (Kebyn, 2026-09-02): trayectoria del root para "saltar" explicito
    de 3 puntos (despegue=a, pico=b, aterrizaje=c) como UNA SOLA parabola
    continua sobre TODA la duracion del salto -- no dos mitades
    independientes (eso se veia como "dos saltos" pegados, reportado por
    Kebyn). El componente horizontal (X/Y) sigue a->b en la primera mitad
    del tiempo y b->c en la segunda (asi el trayecto pasa exactamente por
    el pico marcado, por si b no esta perfectamente a mitad de camino),
    pero el componente vertical es una unica parabola 4*height*t*(1-t)
    evaluada sobre t en [0,1] de PUNTA A PUNTA del salto -- sube y baja UNA
    sola vez, con pico exacto de `height` metros (fijo, 1m por defecto,
    pedido explicito de Kebyn) por encima de la recta entre a.z y c.z en
    t=0.5, sin importar si a/b/c estan a la misma altura de terreno (caso
    tipico: salto sobre un obstaculo en terreno plano).

    Retorna el texto Python de ROOT_LOCATION_DATA.
    """
    n_samples = min(total_frames, 15)
    stride = max(1, (total_frames - 1) // (n_samples - 1))
    rel_frames = list(range(0, total_frames - 1, stride))
    rel_frames.append(total_frames - 1)
    seen = set()
    rel_frames = [rf for rf in rel_frames if not (rf in seen or seen.add(rf))]

    lines = ["ROOT_LOCATION_DATA = {"]
    for rf in rel_frames:
        t = rf / max(total_frames - 1, 1)

        # Horizontal: dos tramos suavizados (a->b, b->c) para pasar
        # exactamente por el pico marcado, sin frenar/arrancar en seco.
        if t <= 0.5:
            t_local = t / 0.5
            t_s = t_local * t_local * (3.0 - 2.0 * t_local)
            x = a['x'] + t_s * (b['x'] - a['x'])
            y = a['y'] + t_s * (b['y'] - a['y'])
        else:
            t_local = (t - 0.5) / 0.5
            t_s = t_local * t_local * (3.0 - 2.0 * t_local)
            x = b['x'] + t_s * (c['x'] - b['x'])
            y = b['y'] + t_s * (c['y'] - b['y'])

        # Vertical: UNA parabola continua de punta a punta del salto.
        z_base = a['z'] + t * (c['z'] - a['z'])
        arc = 4.0 * height * t * (1.0 - t)
        z = z_base + arc

        frame = start_frame + rf
        lines.append(f"    {frame}: ({x:.6f}, {y:.6f}, {z:.6f}),")
    lines.append("}")
    return "\n".join(lines)


def generate_saltar(slot_index, start_frame, points, today, root_rot=(0, 0, -90), altura_pico=1.0):
    """
    NUEVO (Kebyn, 2026-09-02): salto explicito de 3 puntos consecutivos
    marcados a mano por el usuario (tipo_segmento=SALTAR en el Paso 1) --
    despegue=points[0], pico=points[1], aterrizaje=points[2]. UN SOLO
    salto (no tres): la trayectoria del root es una unica parabola continua
    (ver _fmt_root_arc_3pt) con pico fijo de `altura_pico` metros (1m por
    defecto), y la animacion de los bones se RECICLA de saltar_bajar
    (KEYFRAMES_SALTAR_BAJAR) aplicada UNA SOLA VEZ -- no tiled -- para que
    sea un unico ciclo de salto sincronizado con el arco, no dos saltos
    encadenados.
    """
    total_frames = FRAMES_SALTAR_BAJAR
    end_frame = start_frame + total_frames - 1

    p0 = points[0]['coordinates']   # despegue
    p1 = points[1]['coordinates']   # pico
    p2 = points[2]['coordinates']   # aterrizaje
    traj = _fmt_trajectory(points)
    kf_source = _scale_wing_keyframes(KEYFRAMES_SALTAR_BAJAR, ALETEO_FACTOR_SALTAR)
    kf = _fmt_keyframes(kf_source, start_frame)
    root_arc = _fmt_root_arc_3pt(p0, p1, p2, start_frame, total_frames, height=altura_pico)
    rx, ry, rz = root_rot

    code = f'''# -*- coding: utf-8 -*-
"""
slot_{slot_index:03d}_saltar.py
{ENTITY_NAME} - Slot {slot_index}

GENERADO AUTOMÁTICAMENTE
Fecha de generación: {today}
"""

import bpy
import math

# ── Compat fcurves Blender <5.0 / >=5.0 (Action.fcurves eliminado; las curvas
#    viven en action.layers[0].strips[0].channelbags[0]) ──
def _fcs(_action):
    _legacy = getattr(_action, 'fcurves', None)
    if _legacy is not None:
        return _legacy
    try:
        return _action.layers[0].strips[0].channelbags[0].fcurves
    except (IndexError, AttributeError):
        return []

# ============================================
# CONFIGURACIÓN DEL SLOT
# ============================================

SLOT_INDEX = {slot_index}
START_FRAME = {start_frame}
END_FRAME = {end_frame}  # {start_frame} + {total_frames} - 1
TOTAL_FRAMES = {total_frames}

# ============================================
# DATOS DE TRAYECTORIA EMBEBIDOS - SLOT {slot_index}
# ============================================

{traj}

# ============================================
# FIN DE CONFIGURACIÓN DEL SLOT {slot_index}
# ============================================

ANIMATION_INFO = {{
    'name': 'slot_{slot_index:03d}_saltar.py',
    'frame_count': {total_frames},
    'fps': 24,
    'duration_seconds': {total_frames/24:.2f},
    'entity': '{ENTITY_NAME}',
    'slot': {slot_index},
    'movement_type': 'saltar',
    'minecraft_scale': '1_block_=_1m3',
    'narrative_importance': 'movement',
    'rig_type': 'full_armature',
    'source': 'chicken_1_rig',
    'bones_animated': {len(KEYFRAMES_SALTAR_BAJAR)},
    'animation_type': 'jump',
    'bones_reciclados_de': 'saltar_bajar'
}}

# Root Location: despegue {points[0]['index']} {(p0['x'], p0['y'], p0['z'])} -> pico {points[1]['index']} {(p1['x'], p1['y'], p1['z'])} -> aterrizaje {points[2]['index']} {(p2['x'], p2['y'], p2['z'])}
# Trayectoria en DOS tramos (a->b subida, b->c bajada) pasando exactamente
# por el pico marcado -- no se agrega curvatura sintetica.

{root_arc}

def _compute_direction_angle(p0, p1):
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = math.degrees(math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    ang = ang_rounded if ang_diff < 45 else -ang_raw
    while ang >  180: ang -= 360
    while ang < -180: ang += 360
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang

def _smoothstep_val(x):
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)

def _angle_diff_shortest(target, current):
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d

# --- Orientación por trayectoria (despegue->aterrizaje) con RotationSmoother ---
_p0_coords = {{'x': {p0['x']}, 'y': {p0['y']}, 'z': {p0['z']}}}
_p2_coords = {{'x': {p2['x']}, 'y': {p2['y']}, 'z': {p2['z']}}}
_dir_angle  = _compute_direction_angle(_p0_coords, _p2_coords)
_base_rz    = {rz}

def _build_rotation_data():
    import math as _math
    data = {{}}
    target_rz = _dir_angle if _dir_angle is not None else _base_rz
    smoothing = 8

    prev_rot  = _base_rz
    trans_start = None
    trans_start_rot = None

    for frame in range({start_frame}, {end_frame + 1}):
        angle_diff = _angle_diff_shortest(target_rz, prev_rot)
        if abs(angle_diff) < 0.1:
            smoothed = target_rz
            trans_start = None
        else:
            if trans_start is None:
                trans_start = frame
                trans_start_rot = prev_rot
            elapsed  = frame - trans_start
            progress = min(elapsed / smoothing, 1.0)
            eased    = _smoothstep_val(progress)
            smoothed = trans_start_rot + _angle_diff_shortest(target_rz, trans_start_rot) * eased
            if progress >= 1.0:
                prev_rot   = target_rz
                trans_start = None

        data[frame] = (_math.radians({rx}), _math.radians({ry}), _math.radians(smoothed))
    return data

ROOT_ROTATION_DATA = _build_rotation_data()
ROOT_ROTATION_X = {rx}
ROOT_ROTATION_Y = {ry}
ROOT_ROTATION_Z = {rz}  # base; la orientacion real viene del trayecto despegue->aterrizaje

{kf}


def execute_animation(player_parts, start_frame=None, end_frame=None):
    """
    Slot {slot_index}: Animación de saltar (3 puntos) de {ENTITY_NAME}
    """
    start_frame = START_FRAME
    end_frame = END_FRAME

    armature = bpy.data.objects.get("{ARMATURE_NAME}")
    if not armature or armature.type != 'ARMATURE':
        print("Error: No se encontró el Armature '{ARMATURE_NAME}'")
        return False

    if armature.mode != 'POSE':
        bpy.context.view_layer.objects.active = armature
        bpy.ops.object.mode_set(mode='POSE')

    root_obj = next((o for o in bpy.data.objects if o.name == "{ROOT_OBJECT_NAME}"), None)

    _arm_action_name  = f'slot_{{{slot_index}:03d}}_{ENTITY_NAME}_saltar_arm'
    _root_action_name = f'slot_{{{slot_index}:03d}}_{ENTITY_NAME}_saltar_root'

    if not armature.animation_data:
        armature.animation_data_create()
    _arm_existing = bpy.data.actions.get(_arm_action_name)
    if _arm_existing:
        bpy.data.actions.remove(_arm_existing)
    _arm_action = bpy.data.actions.new(name=_arm_action_name)
    armature.animation_data.action = _arm_action

    if root_obj:
        if not root_obj.animation_data:
            root_obj.animation_data_create()
        _root_existing = bpy.data.actions.get(_root_action_name)
        if _root_existing:
            bpy.data.actions.remove(_root_existing)
        _root_action = bpy.data.actions.new(name=_root_action_name)
        root_obj.animation_data.action = _root_action

    bones_applied = 0
    bones_missing = []
    for bone_name, keyframes in KEYFRAME_DATA.items():
        bone = armature.pose.bones.get(bone_name)
        if not bone:
            bones_missing.append(bone_name)
            continue
        bone.rotation_mode = 'XYZ'
        for frame, rotation in keyframes.items():
            bone.rotation_euler = rotation
            bone.keyframe_insert(data_path="rotation_euler", frame=frame)
        bones_applied += 1

    print(f"Keyframes aplicados a {{bones_applied}} bones")
    if bones_missing:
        print(f"  AVISO: huesos no encontrados en el armature: {{bones_missing}}")

    if root_obj:
        for frame, rotation in ROOT_ROTATION_DATA.items():
            root_obj.rotation_euler = rotation
            root_obj.keyframe_insert(data_path="rotation_euler", frame=frame)
        for frame, location in ROOT_LOCATION_DATA.items():
            root_obj.location = location
            root_obj.keyframe_insert(data_path="location", frame=frame)

    if armature.animation_data and armature.animation_data.action:
        for fcurve in _fcs(armature.animation_data.action):
            for kp in fcurve.keyframe_points:
                kp.interpolation = 'BEZIER'
                kp.easing = 'AUTO'

    if root_obj and root_obj.animation_data and root_obj.animation_data.action:
        for fcurve in _fcs(root_obj.animation_data.action):
            for kp in fcurve.keyframe_points:
                kp.interpolation = 'BEZIER'
                kp.easing = 'AUTO'

    print("ANIMACIÓN DE SALTAR (3 PUNTOS) APLICADA!")
    print(f"  Frames: {{start_frame}}-{{end_frame}}")

    if armature.animation_data and armature.animation_data.action:
        _arm_done  = armature.animation_data.action
        armature.animation_data.action = None
        _arm_track = armature.animation_data.nla_tracks.new()
        _arm_track.name = f'Slot_{slot_index:03d}_arm'
        _arm_strip = _arm_track.strips.new(_arm_done.name, start_frame, _arm_done)
        _arm_strip.frame_end      = end_frame
        _arm_strip.extrapolation  = 'NOTHING'
        _arm_strip.use_auto_blend = False
        _arm_strip.blend_in       = 0
        _arm_strip.blend_out      = 0

    if root_obj and root_obj.animation_data and root_obj.animation_data.action:
        _root_done  = root_obj.animation_data.action
        root_obj.animation_data.action = None
        _root_track = root_obj.animation_data.nla_tracks.new()
        _root_track.name = f'Slot_{slot_index:03d}_root'
        _root_strip = _root_track.strips.new(_root_done.name, start_frame, _root_done)
        _root_strip.frame_end      = end_frame
        _root_strip.extrapolation  = 'HOLD_FORWARD'
        _root_strip.use_auto_blend = False
        _root_strip.blend_in       = 0
        _root_strip.blend_out      = 0

    return True


if __name__ == "__main__":
    execute_animation(None, start_frame=START_FRAME, end_frame=END_FRAME)
'''
    return code, end_frame


