# NOTA sobre ejes: se asume la MISMA convencion de ejes locales que usan
# KEYFRAMES_SALTAR_BAJAR / KEYFRAMES_CAMINAR_CYCLE para los huesos de
# columna/cuello/patas (rotacion X = "cabeceo" adelante/atras, Z = giro
# lateral). No se pudo verificar la orientacion de rest exacta de cada
# hueso contra chicken_1.json (el export solo trae bone_count, no las
# matrices de rest por hueso) -- revisar visualmente en Blender y ajustar
# signos si algun hueso gira al reves de lo esperado.

