def _retime_walk_cycle(kf_dict, new_total_frames):
    """
    NUEVO (Lento/Normal/Rapido): re-escala en el tiempo un ciclo de caminata
    denso (una key por cada frame entero 0..N-1, como KEYFRAMES_CAMINAR_CYCLE)
    a una nueva duracion total, por interpolacion lineal entre las dos poses
    capturadas mas cercanas.

    chicken_1 solo tiene UN ciclo de caminata realmente capturado (a
    diferencia del motor multi-estilo de Alfred). En vez de necesitar una
    nueva captura de referencia para cada velocidad, reproducimos la MISMA
    secuencia de poses mas lento (mas frames -> Caminar Lento) o mas rapido
    (menos frames -> Caminar Rapido). El root sigue yendo del mismo punto A
    al mismo punto B, asi que un ciclo mas largo cubre esa misma distancia
    en mas tiempo (mas lento) y uno mas corto la cubre en menos tiempo (mas
    rapido) -- efecto de velocidad correcto sin tocar la trayectoria.
    """
    orig_len = max(next(iter(kf_dict.values())).keys()) + 1
    if new_total_frames == orig_len:
        return kf_dict
    scale = (orig_len - 1) / max(new_total_frames - 1, 1)
    new_dict = {}
    for bone, frames in kf_dict.items():
        new_frames = {}
        for nf in range(new_total_frames):
            orig_pos = nf * scale
            f0 = int(math.floor(orig_pos))
            f1 = min(f0 + 1, orig_len - 1)
            frac = orig_pos - f0
            r0 = frames[f0]
            r1 = frames[f1]
            new_frames[nf] = tuple(r0[i] + (r1[i] - r0[i]) * frac for i in range(3))
        new_dict[bone] = new_frames
    return new_dict


# Factores de velocidad relativos al ciclo Normal capturado (41 frames).
# >1.0 = mas frames por ciclo = mas lento. <1.0 = menos frames = mas rapido.
_WALK_FACTOR_LENTO      = 1.35
_WALK_FACTOR_RAPIDO     = 0.70
# NUEVO (Kebyn, pedido "correr siendo perseguido"): mas rapido que RAPIDO
# -- carrera de panico, zancada corta y frenetica.
# Kebyn pidio duplicar la velocidad de desplazamiento de PERSEGUIDO -> se
# reduce el factor a la mitad (0.55 / 2 = 0.275): mismo mecanismo que
# LENTO/RAPIDO (menos frames de ciclo = misma distancia entre waypoints
# recorrida en la mitad de tiempo = doble velocidad de desplazamiento, y de
# paso el doble de frecuencia de zancada).
_WALK_FACTOR_PERSEGUIDO = 0.275

FRAMES_CAMINAR_CICLO_NORMAL     = FRAMES_CAMINAR_CICLO  # 41, sin cambios (el actual)
FRAMES_CAMINAR_CICLO_LENTO      = max(4, round(FRAMES_CAMINAR_CICLO_NORMAL * _WALK_FACTOR_LENTO))
FRAMES_CAMINAR_CICLO_RAPIDO     = max(4, round(FRAMES_CAMINAR_CICLO_NORMAL * _WALK_FACTOR_RAPIDO))
FRAMES_CAMINAR_CICLO_PERSEGUIDO = max(4, round(FRAMES_CAMINAR_CICLO_NORMAL * _WALK_FACTOR_PERSEGUIDO))

_WALK_CYCLE_CACHE = {}


def _apply_perseguido_overlay(kf_dict, cycle_len):
    """
    NUEVO (Kebyn, pedido "correr siendo perseguido"): devuelve una COPIA
    de kf_dict (ciclo de caminar ya retimed a PERSEGUIDO) con encimado
    ADITIVO de panico -- no reemplaza el ciclo base (las patas/root
    siguen corriendo igual que RAPIDO, solo mas rapido), solo le suma
    encima:

      1. Aleteo frenetico de alas (2 golpes de ala por zancada,
         Scapula en Z + Shoulder en Z (FIX Kebyn, antes X) + Elbow en X,
         con leve retardo de fase --
         mismas relaciones de amplitud que _flap() en
         _keyframes_aletear_1(), pero mas rapido y superpuesto al
         balanceo natural del ciclo de caminar en vez de reemplazarlo).
      2. Una mirada hacia atras por zancada: Head en Z (con tilt en X);
         Neck gira en Y (-Y..+Y, ver FIX Kebyn mas abajo, ya no en Z).
      3. NUEVO (fix "reproduce perseguido pero se ve caminando"): el
         retimed puro (solo tocar velocidad) conserva la MISMA pose de
         caminata (zancada corta, rodilla casi fija, torso recto) solo
         reproducida mas rapido -- eso se lee como "caminar rapido", no
         como correr. Para que se lea como carrera real se amplifica
         la propia oscilacion del ciclo (respecto a su propio promedio,
         sin tocar la pose base) en:
           a) Hip_R/L Z  -> zancada mas larga (mas alcance adelante/atras)
           b) Ankle_R/L Z -> golpe de tobillo mas marcado (empuje/flexion)
           c) Knee_R/L Z -> flexion extra de rodilla SOLO durante la fase
              en que esa pata esta por encima de su propio promedio de
              cadera (fase de vuelo/recobro de esa pata), para que el pie
              se "recoja" en vez de arrastrarse -- rasgo clasico de correr
              vs caminar.
           d) Chest_M / Spine1_M Z -> inclinacion sostenida hacia delante
              (sprint lean), en el mismo signo que ya usa el ciclo de
              caminata capturado (Root/Spine1 solo se mueven en Z negativo
              durante el paso), no un signo inventado.
         AVISO: (c) y (d) asumen que "hip_phase > 0" y "Z negativo" ya
         corresponden a "pata adelantandose" / "inclinacion hacia
         adelante" en este armature (inferido de que el ciclo capturado
         solo usa el lado negativo de Z y vuelve a 0 en reposo). Si al
         revisar en Blender la rodilla se recoge en el paso equivocado o
         la inclinacion se ve hacia atras, invertir el signo de KNEE_LIFT
         o de LEAN_CHEST/LEAN_SPINE mas abajo.

    No requiere una captura de referencia nueva (a diferencia de lo que
    necesitarian HERIDO o un CORRER con zancada real distinta) porque es
    una superposicion procedural sobre huesos que YA existen en el
    ciclo capturado.
    """
    import copy
    out = {bone: dict(kfs) for bone, kfs in kf_dict.items()}
    n = max(cycle_len - 1, 1)

    # ---- (a)+(b) zancada mas larga: amplifica oscilacion respecto al
    # propio promedio del ciclo, no reemplaza la pose base ----
    STRIDE_GAIN = 1.45   # Hip: zancada ~45% mas larga que "Rapido"
    ANKLE_GAIN = 1.30    # Ankle: golpe de tobillo mas marcado

    def _amplify_axis(bone_name, axis_idx, gain):
        if bone_name not in out:
            return
        vals = out[bone_name]
        mean = sum(v[axis_idx] for v in vals.values()) / len(vals)
        for f, v in vals.items():
            newv = list(v)
            newv[axis_idx] = mean + (v[axis_idx] - mean) * gain
            vals[f] = tuple(newv)

    for bone in ('Hip_R_chicken_1', 'Hip_L_chicken_1'):
        _amplify_axis(bone, 2, STRIDE_GAIN)
    for bone in ('Ankle_R_chicken_1', 'Ankle_L_chicken_1'):
        _amplify_axis(bone, 2, ANKLE_GAIN)

    # ---- (c) recogida de rodilla en fase de vuelo de cada pata ----
    KNEE_LIFT = 0.35  # rad, flexion extra en el pico de la fase de vuelo
    for hip_bone, knee_bone in (('Hip_R_chicken_1', 'Knee_R_chicken_1'),
                                 ('Hip_L_chicken_1', 'Knee_L_chicken_1')):
        if hip_bone not in out or knee_bone not in out:
            continue
        hip_vals = out[hip_bone]
        hip_mean = sum(v[2] for v in hip_vals.values()) / len(hip_vals)
        hip_span = max((abs(v[2] - hip_mean) for v in hip_vals.values()), default=0.0) or 1.0
        for f in range(cycle_len):
            hv = hip_vals.get(f)
            if hv is None:
                continue
            hip_phase = (hv[2] - hip_mean) / hip_span
            lift = max(0.0, hip_phase) * KNEE_LIFT
            base = out[knee_bone].get(f, (0.0, 0.0, 0.0))
            out[knee_bone][f] = (base[0], base[1], base[2] - lift)

    # ---- (d) inclinacion sostenida hacia delante (sprint lean) ----
    LEAN_CHEST = -0.12
    LEAN_SPINE = -0.08
    for bone_name, lean in (('Chest_M_chicken_1', LEAN_CHEST),
                             ('Spine1_M_chicken_1', LEAN_SPINE)):
        if bone_name not in out:
            continue
        for f, v in out[bone_name].items():
            out[bone_name][f] = (v[0], v[1], v[2] + lean)

    WING_Z_BONES = ('Scapula_R_chicken_1', 'Scapula_L_chicken_1')
    WING_X_SHOULDER = ('Shoulder_R_chicken_1', 'Shoulder_L_chicken_1')
    WING_X_ELBOW = ('Elbow_R_chicken_1', 'Elbow_L_chicken_1')

    AMP_FLAP = 0.42
    N_BEATS = 2  # 2 aleteos por zancada -- panico, mas rapido que en el lugar

    def _bump(t, center, width):
        """Joroba suave (raised-cosine) centrada en `center`, ancho
        `width`, distancia ciclica (envuelve en 0..1). 0 fuera de la
        joroba, 1 en el centro."""
        d = abs(((t - center + 0.5) % 1.0) - 0.5)
        if d >= width / 2:
            return 0.0
        return 0.5 * (1 + math.cos(math.pi * (d / (width / 2))))

    for f in range(cycle_len):
        t = f / n
        flap = AMP_FLAP * math.sin(2 * math.pi * N_BEATS * t)
        flap_elbow = AMP_FLAP * math.sin(2 * math.pi * N_BEATS * t - 0.45)  # leve retardo (secondary motion)
        look = _bump(t, center=0.55, width=0.42)  # 0..1
        # FIX (Kebyn): Neck_M_chicken_1 debe girar en Y (-Y°..+Y°), no en Z.
        # Antes era un "bajon" unidireccional en Z (0 a -0.85, nunca positivo).
        # Ahora es un giro simetrico en Y, una oscilacion completa por ciclo
        # (mira sobre un hombro y luego sobre el otro), sin tocar Z.
        NECK_TURN_AMP = 0.45  # rad (~25.8 deg) de giro en Y a cada lado
        neck_y = NECK_TURN_AMP * math.sin(2 * math.pi * t)
        # FIX (Kebyn): Head_M_chicken_1 igual que Neck -- gira en Y, no en
        # Z/X. Antes era head_x en X + head_z en Z (dip unidireccional).
        # Ahora es un solo termino en Y, misma forma/timing (joroba en
        # t=0.55) y misma magnitud que el termino dominante anterior
        # (-0.55), para que Head acompañe el giro de Neck en el mismo eje.
        head_y = -0.55 * look

        for bone in WING_Z_BONES:
            if bone not in out:
                continue
            base = out[bone].get(f, (0.0, 0.0, 0.0))
            out[bone][f] = (base[0], base[1], base[2] + flap)
        for bone in WING_X_SHOULDER:
            if bone not in out:
                continue
            base = out[bone].get(f, (0.0, 0.0, 0.0))
            # FIX (Kebyn): Shoulder_R/L oscilan en Z, no en X.
            out[bone][f] = (base[0], base[1], base[2] + flap * 0.8)
        for bone in WING_X_ELBOW:
            if bone not in out:
                continue
            base = out[bone].get(f, (0.0, 0.0, 0.0))
            out[bone][f] = (base[0] + flap_elbow * 0.5, base[1], base[2])

        if 'Neck_M_chicken_1' in out:
            base = out['Neck_M_chicken_1'].get(f, (0.0, 0.0, 0.0))
            # Z forzado a 0.0: el pedido explicito es "no rotar en Z"
            # (el pequeno Z capturado en el ciclo base, hasta ~0.02 rad,
            # tambien se descarta para cumplirlo estrictamente).
            out['Neck_M_chicken_1'][f] = (base[0], base[1] + neck_y, 0.0)
        if 'Head_M_chicken_1' in out:
            base = out['Head_M_chicken_1'].get(f, (0.0, 0.0, 0.0))
            # Z y X forzados a base original (sin overlay): el overlay
            # completo ahora vive en Y, junto con Neck.
            out['Head_M_chicken_1'][f] = (base[0], base[1] + head_y, base[2])

    return out


def _get_walk_cycle(walk_style):
    """
    Devuelve (kf_dict, cycle_len) para el estilo de caminata pedido.

    Implementados por ahora: NORMAL (el ciclo capturado, sin cambios),
    LENTO y RAPIDO (mismo ciclo, retimed), y PERSEGUIDO (ciclo retimed
    aun mas rapido que RAPIDO + encimado procedural de aleteo panico y
    mirada hacia atras -- ver _apply_perseguido_overlay(), no es una
    captura nueva). HERIDO y CORRER (trote liso) todavia no tienen
    implementacion propia (necesitarian una captura de referencia
    distinta, no solo un cambio de velocidad) -- si se piden, caen de
    vuelta a NORMAL para no romper el selector del panel.
    """
    style = (walk_style or 'NORMAL').upper()
    if style not in ('LENTO', 'NORMAL', 'RAPIDO', 'PERSEGUIDO'):
        style = 'NORMAL'
    if style in _WALK_CYCLE_CACHE:
        return _WALK_CYCLE_CACHE[style]

    if style == 'NORMAL':
        result = (KEYFRAMES_CAMINAR_CYCLE, FRAMES_CAMINAR_CICLO_NORMAL)
    elif style == 'LENTO':
        result = (_retime_walk_cycle(KEYFRAMES_CAMINAR_CYCLE, FRAMES_CAMINAR_CICLO_LENTO),
                   FRAMES_CAMINAR_CICLO_LENTO)
    elif style == 'RAPIDO':
        result = (_retime_walk_cycle(KEYFRAMES_CAMINAR_CYCLE, FRAMES_CAMINAR_CICLO_RAPIDO),
                   FRAMES_CAMINAR_CICLO_RAPIDO)
    else:  # PERSEGUIDO
        base = _retime_walk_cycle(KEYFRAMES_CAMINAR_CYCLE, FRAMES_CAMINAR_CICLO_PERSEGUIDO)
        result = (_apply_perseguido_overlay(base, FRAMES_CAMINAR_CICLO_PERSEGUIDO),
                   FRAMES_CAMINAR_CICLO_PERSEGUIDO)

    _WALK_CYCLE_CACHE[style] = result
    return result


def generate_caminar(slot_index, start_frame, points, today, root_rot=(0, 0, -90), walk_style=None):
    import math as _math
    rx, ry, rz = root_rot
    n_pts = len(points)
    n_repeats = max(1, n_pts - 1)
    kf_dict, cycle_len = _get_walk_cycle(walk_style)
    total_frames = n_repeats * (cycle_len - 1) + 1
    end_frame = start_frame + total_frames - 1
    traj = _fmt_trajectory(points)
    kf = _fmt_keyframes_tiled(kf_dict, start_frame, n_repeats)

    # NUEVO (fix "reproduce perseguido pero se ve caminando"): con velocidad
    # sola, el root_obj sigue trasladandose en linea recta y PLANA entre los
    # 2 puntos por tramo (lerp sin ningun rebote vertical) -- eso es lo que
    # hace que, aunque las patas se muevan rapido, el desplazamiento global
    # se lea como "deslizarse rapido" y no como correr (correr real tiene
    # rebote del centro de masa, 2 apoyos por ciclo completo = 1 por pata).
    # Para PERSEGUIDO se insertan puntos intermedios por tramo con un rebote
    # en Z superpuesto al lerp recto (no reemplaza la trayectoria X/Y).
    _is_perseguido = (walk_style or '').upper() == 'PERSEGUIDO'
    _BOUNCE_AMP = 0.05    # metros -- ajustar a ojo en Blender si se ve poco/mucho
    _BOUNCE_PEAKS = 2     # 2 apoyos (pata der + pata izq) por ciclo completo
    _BOUNCE_SUBSTEPS = 8  # puntos intermedios por tramo para dibujar el rebote

    # Ubicación del root por tramo (lerp lineal dentro de cada repetición del ciclo)
    loc_lines = ["ROOT_LOCATION_DATA = {"]
    for rep in range(n_repeats):
        c0 = points[rep]['coordinates']
        c1 = points[rep + 1]['coordinates']
        f0 = start_frame + rep * (cycle_len - 1)
        f1 = f0 + (cycle_len - 1)
        if _is_perseguido and (f1 - f0) >= _BOUNCE_SUBSTEPS:
            for s in range(_BOUNCE_SUBSTEPS):
                frac = s / _BOUNCE_SUBSTEPS
                f = f0 if s == 0 else f0 + round(frac * (f1 - f0))
                bx = c0['x'] + (c1['x'] - c0['x']) * frac
                by = c0['y'] + (c1['y'] - c0['y']) * frac
                bz = c0['z'] + (c1['z'] - c0['z']) * frac
                bounce = abs(math.sin(frac * math.pi * _BOUNCE_PEAKS)) * _BOUNCE_AMP
                loc_lines.append(f"    {f}: ({bx}, {by}, {bz + bounce}),")
            if rep == n_repeats - 1:
                loc_lines.append(f"    {f1}: ({c1['x']}, {c1['y']}, {c1['z']}),")
        else:
            loc_lines.append(f"    {f0}: ({c0['x']}, {c0['y']}, {c0['z']}),")
            if rep == n_repeats - 1:
                loc_lines.append(f"    {f1}: ({c1['x']}, {c1['y']}, {c1['z']}),")
    loc_lines.append("}")
    loc_block = "\n".join(loc_lines)

    # Orientación por tramo: lista de (frame_inicio, frame_fin, angulo_objetivo)
    dir_lines = ["_SEGMENT_DIRECTIONS = ["]
    for rep in range(n_repeats):
        c0 = points[rep]['coordinates']
        c1 = points[rep + 1]['coordinates']
        f0 = start_frame + rep * (cycle_len - 1)
        f1 = f0 + (cycle_len - 1)
        ang = _compute_direction_angle(c0, c1)
        ang_repr = 'None' if ang is None else f"{ang}"
        dir_lines.append(f"    ({f0}, {f1}, {ang_repr}),")
    dir_lines.append("]")
    dir_block = "\n".join(dir_lines)

    code = f'''# -*- coding: utf-8 -*-
"""
slot_{slot_index:03d}_caminar.py
{ENTITY_NAME} - Slot {slot_index}

GENERADO AUTOMÁTICAMENTE
Fecha de generación: {today}
"""

import bpy
import math

# ── Compat fcurves Blender <5.0 / >=5.0 (Action.fcurves eliminado; las curvas
#    viven en action.layers[0].strips[0].channelbags[0]) ──
def _fcs(_action):
    _legacy = getattr(_action, 'fcurves', None)
    if _legacy is not None:
        return _legacy
    try:
        return _action.layers[0].strips[0].channelbags[0].fcurves
    except (IndexError, AttributeError):
        return []

# ============================================
# CONFIGURACIÓN DEL SLOT
# ============================================

SLOT_INDEX = {slot_index}
START_FRAME = {start_frame}
END_FRAME = {end_frame}  # {start_frame} + {total_frames} - 1
TOTAL_FRAMES = {total_frames}
N_PUNTOS = {n_pts}
N_REPETICIONES_CICLO = {n_repeats}  # ciclo base de caminar = {cycle_len} frames

# ============================================
# DATOS DE TRAYECTORIA EMBEBIDOS - SLOT {slot_index}
# ============================================

{traj}

# ============================================
# FIN DE CONFIGURACIÓN DEL SLOT {slot_index}
# ============================================

ANIMATION_INFO = {{
    'name': 'slot_{slot_index:03d}_caminar.py',
    'frame_count': {total_frames},
    'fps': 24,
    'duration_seconds': {total_frames/24:.2f},
    'entity': '{ENTITY_NAME}',
    'slot': {slot_index},
    'movement_type': 'caminar',
    'minecraft_scale': '1_block_=_1m3',
    'narrative_importance': 'movement',
    'rig_type': 'full_armature',
    'source': 'chicken_1_rig',
    'bones_animated': {len(kf_dict)},
    'animation_type': 'walk_cycle',
    'walk_cycles': {n_repeats},
    'walk_cycle_frames': {cycle_len},
    # NOTA: chicken_1 solo tiene UN ciclo de caminata realmente capturado
    # (a diferencia del motor biomecanico multi-estilo de Alfred Animation
    # Studio). Caminar Lento y Caminar Rapido usan ese MISMO ciclo
    # reproducido mas lento / mas rapido (retimed -- mismas poses, duracion
    # distinta), no una captura nueva. Correr (perseguido) tambien parte de
    # ese mismo ciclo retimed (mas rapido que Rapido) pero le suma encima
    # aleteo panico + mirada hacia atras por zancada (ver
    # _apply_perseguido_overlay() en generate_slots.py) -- tampoco es una
    # captura nueva, es una superposicion procedural. Caminar Herido y
    # Correr (trote liso) todavia no estan implementados (necesitan una
    # captura de referencia propia, no solo un cambio de velocidad) y por
    # ahora caen de vuelta a Normal si se seleccionan en el panel.
    'walk_style_solicitado': '{walk_style or "NORMAL"}',
}}

{loc_block}

{dir_block}

_base_rz = {rz}

def _compute_direction_angle(p0, p1):
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = math.degrees(math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    ang = ang_rounded if ang_diff < 45 else -ang_raw
    while ang >  180: ang -= 360
    while ang < -180: ang += 360
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang

def _smoothstep_val(x):
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)

def _angle_diff_shortest(target, current):
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d

def _build_rotation_data():
    """Orientación suavizada tramo a tramo, usando _SEGMENT_DIRECTIONS."""
    data = {{}}
    smoothing = 8
    prev_rot = _base_rz
    trans_start = None
    trans_start_rot = None

    for (f0, f1, ang) in _SEGMENT_DIRECTIONS:
        target_rz = ang if ang is not None else _base_rz
        for frame in range(f0, f1 + 1):
            angle_diff = _angle_diff_shortest(target_rz, prev_rot)
            if abs(angle_diff) < 0.1:
                smoothed = target_rz
                trans_start = None
            else:
                if trans_start is None:
                    trans_start = frame
                    trans_start_rot = prev_rot
                elapsed  = frame - trans_start
                progress = min(elapsed / smoothing, 1.0)
                eased    = _smoothstep_val(progress)
                smoothed = trans_start_rot + _angle_diff_shortest(target_rz, trans_start_rot) * eased
                if progress >= 1.0:
                    prev_rot = target_rz
                    trans_start = None
            data[frame] = (math.radians({rx}), math.radians({ry}), math.radians(smoothed))
        prev_rot = target_rz

    return data

ROOT_ROTATION_DATA = _build_rotation_data()
ROOT_ROTATION_X = {rx}
ROOT_ROTATION_Y = {ry}
ROOT_ROTATION_Z = {rz}  # base; la orientacion real viene de cada tramo de la trayectoria

{kf}


def execute_animation(player_parts, start_frame=None, end_frame=None):
    """
    Slot {slot_index}: Animación de caminar de {ENTITY_NAME} ({n_repeats} ciclo(s) de {cycle_len} frames)
    """
    start_frame = START_FRAME
    end_frame = END_FRAME

    armature = bpy.data.objects.get("{ARMATURE_NAME}")
    if not armature or armature.type != 'ARMATURE':
        print("Error: No se encontró el Armature '{ARMATURE_NAME}'")
        return False

    if armature.mode != 'POSE':
        bpy.context.view_layer.objects.active = armature
        bpy.ops.object.mode_set(mode='POSE')

    root_obj = next((o for o in bpy.data.objects if o.name == "{ROOT_OBJECT_NAME}"), None)

    _arm_action_name  = f'slot_{{{slot_index}:03d}}_{ENTITY_NAME}_caminar_arm'
    _root_action_name = f'slot_{{{slot_index}:03d}}_{ENTITY_NAME}_caminar_root'

    if not armature.animation_data:
        armature.animation_data_create()
    _arm_existing = bpy.data.actions.get(_arm_action_name)
    if _arm_existing:
        bpy.data.actions.remove(_arm_existing)
    _arm_action = bpy.data.actions.new(name=_arm_action_name)
    armature.animation_data.action = _arm_action

    if root_obj:
        if not root_obj.animation_data:
            root_obj.animation_data_create()
        _root_existing = bpy.data.actions.get(_root_action_name)
        if _root_existing:
            bpy.data.actions.remove(_root_existing)
        _root_action = bpy.data.actions.new(name=_root_action_name)
        root_obj.animation_data.action = _root_action

    bones_applied = 0
    bones_missing = []
    for bone_name, keyframes in KEYFRAME_DATA.items():
        bone = armature.pose.bones.get(bone_name)
        if not bone:
            bones_missing.append(bone_name)
            continue
        bone.rotation_mode = 'XYZ'
        for frame, rotation in keyframes.items():
            bone.rotation_euler = rotation
            bone.keyframe_insert(data_path="rotation_euler", frame=frame)
        bones_applied += 1

    print(f"Keyframes aplicados a {{bones_applied}} bones")
    if bones_missing:
        print(f"  AVISO: huesos no encontrados en el armature: {{bones_missing}}")

    if root_obj:
        for frame, rotation in ROOT_ROTATION_DATA.items():
            root_obj.rotation_euler = rotation
            root_obj.keyframe_insert(data_path="rotation_euler", frame=frame)
        for frame, location in ROOT_LOCATION_DATA.items():
            root_obj.location = location
            root_obj.keyframe_insert(data_path="location", frame=frame)

    if armature.animation_data and armature.animation_data.action:
        for fcurve in _fcs(armature.animation_data.action):
            for kp in fcurve.keyframe_points:
                kp.interpolation = 'BEZIER'
                kp.easing = 'AUTO'

    if root_obj and root_obj.animation_data and root_obj.animation_data.action:
        for fcurve in _fcs(root_obj.animation_data.action):
            for kp in fcurve.keyframe_points:
                kp.interpolation = 'BEZIER'
                kp.easing = 'AUTO'

    print("ANIMACIÓN DE CAMINAR APLICADA!")
    print(f"  Frames: {{start_frame}}-{{end_frame}}  ({n_repeats} ciclo(s))")

    if armature.animation_data and armature.animation_data.action:
        _arm_done  = armature.animation_data.action
        armature.animation_data.action = None
        _arm_track = armature.animation_data.nla_tracks.new()
        _arm_track.name = f'Slot_{slot_index:03d}_arm'
        _arm_strip = _arm_track.strips.new(_arm_done.name, start_frame, _arm_done)
        _arm_strip.frame_end      = end_frame
        _arm_strip.extrapolation  = 'NOTHING'
        _arm_strip.use_auto_blend = False
        _arm_strip.blend_in       = 0
        _arm_strip.blend_out      = 0

    if root_obj and root_obj.animation_data and root_obj.animation_data.action:
        _root_done  = root_obj.animation_data.action
        root_obj.animation_data.action = None
        _root_track = root_obj.animation_data.nla_tracks.new()
        _root_track.name = f'Slot_{slot_index:03d}_root'
        _root_strip = _root_track.strips.new(_root_done.name, start_frame, _root_done)
        _root_strip.frame_end      = end_frame
        _root_strip.extrapolation  = 'HOLD_FORWARD'
        _root_strip.use_auto_blend = False
        _root_strip.blend_in       = 0
        _root_strip.blend_out      = 0

    return True


if __name__ == "__main__":
    execute_animation(None, start_frame=START_FRAME, end_frame=END_FRAME)
'''
    return code, end_frame


# ============================================================
# ENTRADA INTERACTIVA
# ============================================================

def pedir_entero(mensaje, minimo=0):
    while True:
        try:
            v = int(input(mensaje).strip())
            if v < minimo:
                print(f"  El valor debe ser >= {minimo}")
                continue
            return v
        except ValueError:
            print("  Por favor ingresa un número entero válido.")


def pedir_float(mensaje):
    while True:
        try:
            return float(input(mensaje).strip())
        except ValueError:
            print("  Por favor ingresa un número válido.")


def encontrar_json_recorrido(directorio_padre):
    """
    Busca un .json en el directorio padre que contenga key_points
    de trayectoria (top-level o dentro de 'recorrido').
    """
    candidatos = []
    for fname in os.listdir(directorio_padre):
        if not fname.lower().endswith('.json'):
            continue
        ruta = os.path.join(directorio_padre, fname)
        try:
            with open(ruta, encoding='utf-8') as f:
                data = json.load(f)
        except Exception:
            continue
        if 'key_points' in data or ('recorrido' in data and isinstance(data['recorrido'], dict) and 'key_points' in data['recorrido']):
            candidatos.append((fname, ruta, data))
    return candidatos


def extraer_key_points(data):
    if 'key_points' in data:
        return data['key_points']
    if 'recorrido' in data and 'key_points' in data['recorrido']:
        return data['recorrido']['key_points']
    return None


# ============================================================
# MAIN
# ============================================================

def main():
    print("=" * 60)
    print(f"  GENERADOR DE SLOTS - {ENTITY_NAME}")
    print("=" * 60)

    # 1) Localizar el JSON de recorrido
    json_path = None
    if len(sys.argv) > 1 and sys.argv[1].lower().endswith('.json'):
        json_path = sys.argv[1]

    if json_path and os.path.isfile(json_path):
        with open(json_path, encoding='utf-8') as f:
            data = json.load(f)
        key_points = extraer_key_points(data)
        if key_points is None:
            print(f"[ERROR] '{json_path}' no contiene 'key_points' de trayectoria.")
            sys.exit(1)
    else:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        parent_dir = os.path.dirname(script_dir)
        candidatos = encontrar_json_recorrido(parent_dir)
        if not candidatos:
            print(f"[ERROR] No se encontró ningún .json con 'key_points' en: {parent_dir}")
            print("        Pasa la ruta como argumento: python generate_slots.py ruta\\historia_chicken_1.json")
            sys.exit(1)
        elif len(candidatos) == 1:
            fname, ruta, data = candidatos[0]
            print(f"Usando archivo de recorrido: {fname}")
            key_points = extraer_key_points(data)
        else:
            print("Se encontraron varios JSON con trayectoria, elige uno:")
            for i, (fname, ruta, data) in enumerate(candidatos, 1):
                print(f"  {i}. {fname}")
            idx = pedir_entero("Número: ", minimo=1) - 1
            fname, ruta, data = candidatos[idx]
            key_points = extraer_key_points(data)

    print(f"\nPuntos de trayectoria cargados: {len(key_points)}")

    # 2) Parámetros de generación
    slot_inicial = pedir_entero("\nNúmero de slot inicial (ej. 1): ", minimo=1)
    frame_inicial = pedir_entero("Frame inicial en Blender (ej. 1): ", minimo=1)
    rx = pedir_float("Rotación inicial del root - eje X en grados (ej. 0): ")
    ry = pedir_float("Rotación inicial del root - eje Y en grados (ej. 0): ")
    rz = pedir_float("Rotación inicial del root - eje Z en grados (ej. -90): ")
    root_rot = (rx, ry, rz)

    output_dir = None
    for i, arg in enumerate(sys.argv):
        if arg == '--output-dir' and i + 1 < len(sys.argv):
            output_dir = sys.argv[i + 1]
    if not output_dir:
        today_str = date.today().isoformat()
        script_dir = os.path.dirname(os.path.abspath(__file__))
        output_dir = os.path.join(script_dir, f"slots_{ENTITY_NAME}_desde_{slot_inicial}_{today_str}")
    os.makedirs(output_dir, exist_ok=True)

    # 3) Agrupar segmentos y generar
    segments = group_segments(key_points)
    today = date.today().isoformat()

    print(f"\nSegmentos detectados: {len(segments)}")
    resumen = []
    slot_actual = slot_inicial
    frame_actual = frame_inicial

    for seg in segments:
        tipo = seg['type']
        pts = seg['points']

        if tipo == 'saltar_subir':
            code, end_frame = generate_saltar_subir(slot_actual, frame_actual, pts, today, root_rot)
        elif tipo == 'saltar_bajar':
            code, end_frame = generate_saltar_bajar(slot_actual, frame_actual, pts, today, root_rot)
        elif tipo == 'saltar':
            code, end_frame = generate_saltar(slot_actual, frame_actual, pts, today, root_rot)
        else:
            code, end_frame = generate_caminar(slot_actual, frame_actual, pts, today, root_rot)

        out_name = f"slot_{slot_actual:03d}_{tipo}.py"
        out_path = os.path.join(output_dir, out_name)
        with open(out_path, 'w', encoding='utf-8') as f:
            f.write(code)

        print(f"  [{slot_actual:03d}] {tipo:14s}  puntos {pts[0]['index']}->{pts[-1]['index']}  "
              f"frames {frame_actual}-{end_frame}  -> {out_name}")

        resumen.append({
            'slot': slot_actual,
            'tipo': tipo,
            'punto_inicio': pts[0]['index'],
            'punto_fin': pts[-1]['index'],
            'frame_inicio': frame_actual,
            'frame_fin': end_frame,
            'archivo': out_name,
        })

        slot_actual += 1
        frame_actual = end_frame + 1

    resumen_path = os.path.join(output_dir, '_resumen_slots.json')
    with open(resumen_path, 'w', encoding='utf-8') as f:
        json.dump({
            'entity': ENTITY_NAME,
            'generado': today,
            'total_slots': len(resumen),
            'slots': resumen,
        }, f, indent=2, ensure_ascii=False)

    print(f"\n{len(resumen)} slots generados en: {output_dir}")
    print(f"Resumen guardado en: {resumen_path}")


if __name__ == "__main__":
    main()
